 void await(BooleanSupplier condition,String message)throws Exception{long until=SystemClock.uptimeMillis()+10000;while(SystemClock.uptimeMillis()<until){if(condition.getAsBoolean()){checks++;return;}Thread.sleep(60);}throw new AssertionError(message);}
